/**
 * What the machine asks for, and of whom.
 *
 * `ToUi` is far larger than `ToSource` because the whole screen crosses in
 * one action (see [`ActionUi::Render`]). Boxing would not help — UniFFI
 * copies the payload across the boundary either way.
 */

public enum Action: Equatable, Hashable {
    
    case toUi(action: ActionUi
    )
    case toSource(action: ActionSource
    )





}

#if compiler(>=6)
extension Action: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAction: FfiConverterRustBuffer {
    typealias SwiftType = Action

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Action {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .toUi(action: try FfiConverterTypeActionUi.read(from: &buf)
        )
        
        case 2: return .toSource(action: try FfiConverterTypeActionSource.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Action, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .toUi(action):
            writeInt(&buf, Int32(1))
            FfiConverterTypeActionUi.write(action, into: &buf)
            
        
        case let .toSource(action):
            writeInt(&buf, Int32(2))
            FfiConverterTypeActionSource.write(action, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAction_lift(_ buf: RustBuffer) throws -> Action {
    return try FfiConverterTypeAction.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAction_lower(_ value: Action) -> RustBuffer {
    return FfiConverterTypeAction.lower(value)
}




public enum ActionSource: Equatable, Hashable {
    
    /**
     * Go and get everything. No freshness hint: when to ask a bank again is
     * the server's decision, since a hint the app can repeat at will spends
     * an account-wide Plaid budget.
     */
    case loadSnapshot
    /**
     * Read who the device says is signed in.
     */
    case loadSession
    /**
     * Commit the session the runtime is holding, so that the next launch
     * opens on the Ledger. No payload: the credential is the one `VerifyCode`
     * came back with, and the runtime has held it since.
     */
    case saveSession
    /**
     * Throw the session away, so that the next launch opens on first run.
     */
    case forgetSession
    /**
     * Send a six-digit code to this address.
     */
    case sendCode(email: String
    )
    /**
     * Check a six-digit code against the address it was sent to.
     */
    case verifyCode(email: String, code: String
    )
    /**
     * Say what to call whoever is signed in. Nothing waits on it: the flow
     * has already moved on, and a screen that will not move until a write
     * lands is a screen that stops when the write is slow.
     */
    case setName(name: String
    )
    /**
     * Ask the server for a `link_token` and open the `hosted_link_url` that
     * comes back. The app never holds a token of either kind: the secret that
     * signs both cannot ship inside an app (`docs/PLAID.md`).
     */
    case startBankLink
    /**
     * The same, in update mode against one bank the user already holds: ask
     * the server for a repair session and open its page. The sign-in renews
     * the bank's consent instead of attaching a new one.
     */
    case startBankRepair(itemId: String
    )
    /**
     * Ask the server to remove one bank: stop the Item at Plaid, and delete
     * the accounts, transactions and streams that came through it. There is
     * no undo, and the tap that leads here has been confirmed.
     */
    case removeBank(itemId: String
    )
    /**
     * Ask the server to email the signed-in user the code that confirms
     * deleting their account. No address: the server sends it to the one
     * the account is written to.
     */
    case sendDeleteCode
    /**
     * Delete the account, with the code the email carried. There is no undo:
     * the server answers once the rows are gone.
     */
    case deleteAccount(code: String
    )
    /**
     * Ask the server for a Stripe Checkout page and open it in a window of
     * its own. The money is taken there: no card detail ever reaches this
     * app, and nothing about the page is a thing to put in an event log.
     */
    case startCheckout
    /**
     * Open a stream the server writes the sync's progress to, and report
     * what arrives on it.
     *
     * The runtime holds the connection and chooses how to read it; when to
     * have one at all, and when to try again after losing one, are decisions
     * and stay here — so a replay reproduces every attempt.
     */
    case watchSync
    /**
     * Let that stream go. Its own action rather than something the runtime
     * infers from a screen it cannot see: a connection nobody closes is a
     * connection the server holds a slot for.
     */
    case stopWatchingSync





}

