        )
        
        case 3: return .ended(ranOut: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 4: return .unfinished
        
        case 5: return .unconfirmed
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

